        self.data = data
        self.left = left
        self.right = right

    def __str__(self):
        return f'TreeNode(data={self.data}, left={self.left}, right={self.right})'


class BinarySearchTree:
    def __init__(self, tree_data):
        self.root = None
        if tree_data:
            for item in tree_data:
                self._insert(item)

    def _insert(self, value):
        """
        Helper method to insert a single value into the BST.
        This method maintains the BST property:
        - All data in the left subtree is less than or equal to the current node's data.
        - All data in the right subtree is greater than the current node's data.
        """
        new_node = TreeNode(value)
        if self.root is None:
            self.root = new_node
            return

        current = self.root
        while True:
            if value <= current.data:
                if current.left is None:
                    current.left = new_node
                    return
                else:
                    current = current.left
            else:  # value > current.data
                if current.right is None:
                    current.right = new_node
                    return
                else:
                    current = current.right

    def data(self):
        """
        Returns the root node of the tree.
        """
        return self.root

    def sorted_data(self):
        """
        Returns a list of all data elements in the tree, sorted in ascending order.
        This is achieved by performing an in-order traversal of the BST.
        """
        result = []
        self._in_order_traverse(self.root, result)
        return result

    def _in_order_traverse(self, node, result_list):
        """
        Helper method for recursive in-order traversal.
        It visits the left subtree, then the current node, then the right subtree.
        """
        if node is None:
            return

        self._in_order_traverse(node.left, result_list)
        result_list.append(node.data)
        self._in_order_traverse(node.right, result_list)

